/* @lc app=leetcode id=3333 lang=kotlin */ class Solution { fun possibleStringCount(word: String, k: Int): Int = 1_000_000_007L.let { M -> (word.indices.filter { it == 0 || word[it] != word[it - 1] } + word.length).zipWithNext { a, b -> b - a }.let { runs -> runs.fold(1L) { a, r -> a * r % M }.let { tot -> if (runs.size >= k) tot.toInt() else runs.fold(LongArray(k) { if (it == 0) 1L else 0L }) { dp, r -> dp.runningFold(0L) { a, b -> (a + b) % M }.let { pre -> LongArray(k) { j -> if (j == 0) 0L else ((pre[j] - pre[maxOf(0, j - r)]) % M + M) % M } } }.let { dp -> (((tot - dp.sum()) % M + M) % M).toInt() } } } } }